      {
        "block_id": "Q3s6dhbEkowWxBxlIXgcZmJ6nKh",
        "block_type": 2,
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "An ANN search finds vector embeddings most similar to specified vector embeddings. However, the search results may not always be correct. You can include filtering conditions in a search request so that <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> conducts metadata filtering before conducting ANN searches, reducing the search scope from the whole collection to only the entities matching the specified filtering conditions.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "ZQCddZBuIoCOSRxjH3DcJ1bVn8d",
        "block_type": 4,
        "heading2": {
          "elements": [
            {
              "text_run": {
                "content": "Overview",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe"
      },
      {
        "block_id": "HBY5dAClJo6BDmxXapqcqaxdnZf",
        "block_type": 2,
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "In <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include>, filtered searches are categorized into two types — ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "standard filtering",
                "text_element_style": {
                  "bold": true,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " and ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "iterative filtering",
                "text_element_style": {
                  "bold": true,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " — depending on the stage at which the filtering is applied.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "G5gNdBD3FoYc5rxF46KcM1ninJh",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "Standard filtering",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
