        },
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe"
      },
      {
        "block_id": "VPg4dTVBhovRQxxRZ4FcxuR2ntr",
        "block_type": 2,
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "If a collection contains both vector embeddings and their metadata, you can filter metadata before ANN search to improve the relevancy of the search result. Once <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> receives a search request carrying a filtering condition, it restricts the search scope within the entities matching the specified filtering condition.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "Lu0Ad8pjJo5cB2x5SbAcsyG9nke",
        "block_type": 43,
        "board": {
          "token": "QIeKwvDN1h7lTnb9iJ7cPubknrb"
        },
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe"
      },
      {
        "block_id": "GOfAdj2o9o1DKjxkvcecBQe7nYu",
        "block_type": 2,
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "As shown in the above diagram, the search request carries ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "chunk like \"%red%\"",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " as the filtering condition, indicating that <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> should conduct the ANN search within all the entities that have the word ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "red",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " in the ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "chunk",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " field. Specifically, <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> does the following:",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
