        "block_type": 12,
        "bullet": {
          "elements": [
            {
              "text_run": {
                "content": "Filter entities that match the filtering conditions carried in the search request.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
