        ],
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "The standard filtering process effectively narrows the search scope to a small range. However, overly complex filtering expressions may result in ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "very high search latency",
                "text_element_style": {
                  "bold": false,
                  "comment_ids": [
                    "7462194982179946499"
                  ],
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ". In such cases, iterative filtering can serve as an alternative, helping to reduce the workload of scalar filtering.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "ZdYgdzMxwo44Gkx0PincdNDknWb",
        "block_type": 43,
        "board": {
