      {
        "block_id": "YdDudLDjNo8NQlxvDSScBP8Mn6c",
        "block_type": 2,
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "As illustrated in the diagram above, a search with iterative filtering performs the vector search in iterations. Each entity returned by the iterator undergoes scalar filtering, and this process continues until the specified topK results are achieved.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
