        "block_type": 2,
        "parent_id": "XHMed32msofjsHxd69NcpG8tnhe",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "This method significantly reduces the number of entities subjected to scalar filtering, making it especially beneficial for handling highly complex filtering expressions.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
