        "block_type": 2,
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "In this section, we are going to set up a ColBERT text retrieval system using StructArray. Before that, set up a <include target=\"milvus\">Milvus v2.6.x instance</include><include target=\"zilliz\">Zilliz Cloud cluster compatible with Milvus v2.6.x</include>, and obtain a Cohere access token.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
