        "block_type": 2,
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "In this example, we are going to use Cohere's Wikipedia dataset and retrieve the first 10,000 records. You can find information about this dataset on ",
