                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "link": {
                    "url": "https%3A%2F%2Fhuggingface.co%2Fdatasets%2FCohere%2Fwikipedia-2023-11-embed-multilingual-v3"
                  },
                  "strikethrough": false,
                  "underline": false
