      },
      {
        "block_id": "MbwLdrSPiozB6wxfphGcsJfJnxf",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "from datasets import load_dataset\n\nlang = \"simple\"\ndocs = load_dataset(\n    \"Cohere/wikipedia-2023-11-embed-multilingual-v3\", \n    lang, \n    split=\"train[:10000]\"\n",
