        "code": {
          "elements": [
            {
              "text_run": {
                "content": "df = docs.to_pandas()\ngroups = df.groupby('title')\n\ndata = []\n\nfor title, group in groups:\n  data.append({\n      \"title\": title,\n      \"paragraphs\": [{\n          \"text\": row['text'],\n          'emb': row['emb']\n      } for _, row in group.iterrows()]\n",
