        "text": {
          "elements": [
            {
              "text_run": {
                "content": "According to ColBERT's design, the query text should be tokenized and then embedded into an EmbeddingList. In this step, we will use the same model that Cohere used to generate embeddings for the paragraphs in the Wikipedia dataset.",
                "text_element_style": {
                  "bold": false,
