            }
          ]
        }
      },
      {
        "block_id": "IzuBdgQfyoPYVXxbFJbcJ4pMnJh",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "import cohere\n\nco = cohere.ClientV2(\"COHERE_API_KEY\")\n\nquery_inputs = [\n    {\n        'content': [\n            {'type': 'text', 'text': 'Adobe'},\n        ]\n    },\n    {\n        'content': [\n            {'type': 'text', 'text': 'software'}\n        ]\n    }\n]\n\nembeddings = co.embed(\n    inputs=query_inputs,\n    model='embed-multilingual-v3.0',\n    input_type=\"classification\",\n    embedding_types=[\"float\"],\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
