      {
        "block_id": "FDKmd0amYobSjcxpYC8cjgRCnRd",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "from pymilvus.client.embedding_list import EmbeddingList\n\nquery_emb_list = EmbeddingList()\n\nif (embeddings.embeddings.float):\n  query_emb_list.add_batch(embeddings.embeddings.float)\n\nresults = client.search(\n    collection_name=\"wiki_documents\",\n    data=[query_emb_list],\n    anns_field=\"paragraphs[emb]\",\n    limit=10,\n    output_fields=[\"title\"]\n)\n\nfor hit in results[0]:\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "  print(f\"Document {hit['entity']['title']}: {hit['distance']:.4f}\")",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
