      {
        "block_id": "T2b7dNakVoBOhZxysstcHayHndh",
        "block_type": 2,
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "As illustrated in the ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "Overview",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "link": {
                    "url": "https%3A%2F%2Fzilliverse.feishu.cn%2Fwiki%2FMf7GwGwgQiLCcykOi69cvaD8ncz%23XDC5dUqtxoAmkXx4blxcQ0Asnlc"
                  },
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " section, the ColPali model is a VLM that projects images into the vector space of a text model. In this step, we will use the latest ColPali model ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "vidore/colpali-v1.3",
                "text_element_style": {
                  "bold": true,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ". You can find details about this model on ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "this page",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "link": {
                    "url": "https%3A%2F%2Fhuggingface.co%2Fvidore%2Fcolpali-v1.3"
                  },
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ". ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "LCaddeQJiohvi9xdxSzcLSmLnWd",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "import torch\nfrom typing import cast\nfrom colpali_engine.models import ColPali, ColPaliProcessor\n\nmodel_name = \"vidore/colpali-v1.3\"\n\nmodel = ColPali.from_pretrained(\n    model_name,\n    torch_dtype=torch.bfloat16,\n    device_map=\"cuda:0\",  # or \"mps\" if on Apple Silicon\n).eval()\n\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "processor = ColPaliProcessor.from_pretrained(model_name)",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "language": 49,
            "wrap": false
          }
        },
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf"
      },
      {
        "block_id": "MTCwdrJFyoGhhQxkeXjcZxrGnoG",
        "block_type": 2,
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Once the model is ready, you can try to generate patches for a specific image as follows.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "doxcnSZOCunI1Fn0ZCJWIoPfTUe",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "from PIL import Image\nfrom io import BytesIO\n\n# Use the iterrows() generator to get the first row.\nrow = next(df.iterrows())[1]\n\n# Decode the image bytes and generate patch embeddings.\nimages = [Image.open(BytesIO(row[\"image\"][\"bytes\"]))]\nbatch_images = processor.process_images(images).to(model.device)\n\nwith torch.no_grad():\n    patches_embeddings = model(**batch_images)[0]\n\n# Check the shape of the embeddings generated for the patches.\nprint(patches_embeddings.shape)\n\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "# [1031, 128]",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "language": 49,
            "wrap": false
          }
        },
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf"
      },
      {
        "block_id": "GBYQdUoIjoj6IHx4q6lcFHHFn8m",
        "block_type": 2,
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "In the code above, the ColPali model resizes the image to 448 x 448 pixels, then divides it into patches, each measuring 14 x 14 pixels. Lastly, these patches are embedded into 1,031 embeddings, each with 128 dimensions.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "Zrwcd1SlAo3iI9xhV65cxOxCnIb",
        "block_type": 2,
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "You can generate embeddings for all the images using a loop as follows:",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "doxcnBBQzznbsvs42Xi4ZCwd9ph",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "data = []\n\nfor _, row in df.iterrows():\n    corpus_id = row[\"corpus_id\"]\n    images = [Image.open(BytesIO(row[\"image\"][\"bytes\"]))]\n    batch_images = processor.process_images(images).to(model.device)\n\n    with torch.no_grad():\n        patches = model(**batch_images)[0]\n\n    doc_id = row[\"doc_id\"]\n    page_number_in_doc = row[\"page_number_in_doc\"]\n\n    data.append({\n        \"corpus_id\": corpus_id,\n        \"patches\": [\n            {\"emb\": emb.float().cpu().tolist()}\n            for emb in patches\n        ],\n        \"doc_id\": doc_id,\n        \"page_number_in_doc\": page_number_in_doc,\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "    })",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "language": 49,
            "wrap": false
          }
        },
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf"
      },
