      },
      {
        "block_id": "doxcn46plyUmfWCcHgRwdVCjPYf",
        "block_type": 2,
        "parent_id": "I59YdqMpioEHGVxFiqccJawsnZf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Once the data is ready, we will create a collection. In the collection, ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "patches",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " is a StructArray field. Each Struct element stores one patch embedding. For index requirements on StructArray vector subfields, see ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "Index StructArray Fields",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "link": {
                    "url": "https://zilliverse.feishu.cn/wiki/VvkEwug9ciPZYVk6hM1chLydnib"
                  },
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ".",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
