        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Reciprocal Rank Fusion (RRF) Ranker is a reranking strategy for ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "<include target=\"milvus\">",
