        "parent_id": "Lu2ndUPtboOD4AxxuCZcO590n5M",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "RRF Ranker is specifically designed for hybrid search scenarios where you want to balance results from multiple vector search paths without assigning explicit importance weights. It's particularly effective for:",
