      {
        "block_id": "doxcnHsbGHbeS1DEWQAOzBNT7kg",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "import io.milvus.v2.client.ConnectConfig;\nimport io.milvus.v2.client.MilvusClientV2;\nimport io.milvus.v2.service.vector.request.AnnSearchReq;\nimport io.milvus.v2.service.vector.request.HybridSearchReq;\nimport io.milvus.v2.service.vector.response.SearchResp;\nimport io.milvus.v2.service.vector.request.data.EmbeddedText;\nimport io.milvus.v2.service.vector.request.data.FloatVec;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.Collections;\nimport java.util.List;\n\nMilvusClientV2 client = new MilvusClientV2(ConnectConfig.builder()\n\n        .uri(\"http://localhost:19530\")\n\n        .build());\n\nList<AnnSearchReq> searchRequests = new ArrayList<>();\n\nsearchRequests.add(AnnSearchReq.builder()\n\n        .vectorFieldName(\"text_vector\")\n\n        .vectors(Collections.singletonList(new EmbeddedText(\"modern dining table\")))\n\n        .limit(10)\n\n        .build());\n\nsearchRequests.add(AnnSearchReq.builder()\n\n        .vectorFieldName(\"image_vector\")\n\n        .vectors(Collections.singletonList(new FloatVec(imageEmbedding)))\n\n        .limit(10)\n\n        .build());\n\nHybridSearchReq hybridSearchReq = HybridSearchReq.builder()\n\n        .collectionName(collectionName)\n\n        .searchRequests(searchRequests)\n\n        .ranker(rerank)\n\n        .limit(10)\n\n        .outFields(Arrays.asList(\"product_name\", \"price\", \"category\"))\n\n        .build();\n\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "SearchResp searchResp = client.hybridSearch(hybridSearchReq);",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
