        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "import { MilvusClient } from \"@zilliz/milvus2-sdk-node\";",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "\n\nconst milvusClient = new MilvusClient({ address: \"http://localhost:19530\" });\n\nconst text_search = {\n    data: [\"modern dining table\"],\n    anns_field: \"text_vector\",\n    param: {},\n    limit: 10,\n};\n\nconst image_search = {\n  data: [image_embedding],\n  anns_field: \"image_vector\",\n  param: {},\n  limit: 10,\n};\n\nconst search = await milvusClient.search({\n  collection_name: collection_name,\n  data: [text_search, image_search],\n  output_fields: [\"product_name\", \"price\", \"category\"],\n  limit: 10,\n  rerank: rerank,\n",
                "text_element_style": {
