        "parent_id": "BO7ed6hjgoJnXJxGcY6cwuM9n0b",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "In traditional vector search, results are ranked purely by vector similarity—how closely vectors match in mathematical space. But in real-world applications, what makes content truly relevant often depends on more than just semantic similarity.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "B9GgdpAWwow6loxNmtycMvdTnWG",
        "block_type": 2,
        "parent_id": "BO7ed6hjgoJnXJxGcY6cwuM9n0b",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Consider these everyday scenarios:",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "Ix1ydGhvloHGmZxMAvBcTRuen2c",
        "block_type": 12,
        "bullet": {
          "elements": [
            {
              "text_run": {
                "content": "A news search where yesterday's article should rank higher than a similar article from three years ago",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "BO7ed6hjgoJnXJxGcY6cwuM9n0b"
      },
      {
        "block_id": "TIe3dmvAuoSuz7xvW20c1OPynMg",
        "block_type": 12,
        "bullet": {
          "elements": [
            {
              "text_run": {
                "content": "A restaurant finder that prioritizes venues 5 minutes away over those requiring a 30-minute drive",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "BO7ed6hjgoJnXJxGcY6cwuM9n0b"
      },
      {
        "block_id": "BrxGdJDbmoeUoKx2zSMcTDyGnUb",
        "block_type": 12,
        "bullet": {
          "elements": [
            {
              "text_run": {
                "content": "An e-commerce platform that boosts trending products even when they're slightly less similar to the search query",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "BO7ed6hjgoJnXJxGcY6cwuM9n0b"
      },
      {
        "block_id": "G636doXG8oHAEvx9znFcLFCqnz6",
        "block_type": 2,
        "parent_id": "BO7ed6hjgoJnXJxGcY6cwuM9n0b",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "These scenarios all share a common need: balancing vector similarity with other numeric factors like time, distance, or popularity.",
