        "text": {
          "elements": [
            {
              "text_run": {
                "content": "In cases of hybrid search (combining multiple vector fields), ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
