        "text": {
          "elements": [
            {
              "text_run": {
                "content": "For example, if a research paper scores 0.82 from vector similarity and 0.91 from BM25-based text retrieval in a hybrid search, ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
