      {
        "block_id": "doxcnAzrcOXtzlnqxjajbqi4hUe",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "import io.milvus.v2.service.vector.request.ranker.DecayRanker;\nimport java.time.ZoneId;\nimport java.time.ZonedDateTime;\nimport java.util.Collections;\n\nZonedDateTime zdt = ZonedDateTime.of(2025, 1, 25, 0, 0, 0, 0, ZoneId.systemDefault());\n\nDecayRanker rerank = DecayRanker.builder()\n        .name(\"time_decay\")\n        .inputFieldNames(Collections.singletonList(\"timestamp\"))\n        .function(\"gauss\")\n        .origin(zdt.toInstant().toEpochMilli())\n        .scale(7 * 24 * 60 * 60)\n        .offset(24 * 60 * 60)\n        .decay(0.5)\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
